{
  "name": "苏黎世仪器通用控制基类",
  "name_en": "Zurich Instruments Base Control Module",
  "manufacturer": "Zurich Instruments",
  "description": "一个非实体的软件控制基类，用于在实验中通过 LabOne/DAQ 服务器连接和管理多类苏黎世仪器设备。它提供节点读写、订阅与轮询、AWG 程序编译上传、波形表同步、时钟管理以及错误处理等通用功能，供具体仪器驱动复用。",
  "description_en": "A non-physical software base control component used in experiments to connect to and manage multiple Zurich Instruments devices through the LabOne/DAQ server. It provides shared functions for node read/write access, subscriptions and polling, AWG program compilation and upload, waveform-table synchronization, clock handling, and error management for reuse by concrete instrument drivers.",
  "tag_hints": [
    "Zurich Instruments",
    "LabOne DAQ",
    "AWG program upload",
    "waveform synchronization",
    "node-based control",
    "subscription polling",
    "external clock",
    "error handling"
  ],
  "actions": [
    {
      "action_name": "auto-FIXMEclose",
      "description": "断开应用服务器连接",
      "description_en": "disconnect the application server connection"
    },
    {
      "action_name": "auto-assure_ext_clock",
      "description": "确保设备使用外部参考时钟",
      "description_en": "ensure use of an external reference clock"
    },
    {
      "action_name": "auto-check_errors",
      "description": "检查设备或服务器错误状态",
      "description_en": "check device or server error status"
    },
    {
      "action_name": "auto-clear_errors",
      "description": "清除已记录的错误",
      "description_en": "clear recorded errors"
    },
    {
      "action_name": "auto-configure_awg_from_string",
      "description": "将程序字符串编译并上传到指定 AWG",
      "description_en": "compile and upload a program string to the selected AWG"
    },
    {
      "action_name": "auto-demote_error",
      "description": "将指定错误代码降级为警告",
      "description_en": "demote a specified error code to a warning"
    },
    {
      "action_name": "auto-getc",
      "description": "读取复数节点值",
      "description_en": "read a complex node value"
    },
    {
      "action_name": "auto-getd",
      "description": "读取双精度节点值",
      "description_en": "read a double-precision node value"
    },
    {
      "action_name": "auto-getdeep",
      "description": "在超时范围内深度读取节点值",
      "description_en": "read a node value with a deep query and timeout"
    },
    {
      "action_name": "auto-geti",
      "description": "读取整数节点值",
      "description_en": "read an integer node value"
    },
    {
      "action_name": "auto-gets",
      "description": "读取字符串节点值",
      "description_en": "read a string node value"
    },
    {
      "action_name": "auto-getv",
      "description": "读取向量节点值",
      "description_en": "read a vector node value"
    },
    {
      "action_name": "auto-load_default_settings",
      "description": "加载默认设置",
      "description_en": "load default settings"
    },
    {
      "action_name": "auto-plot_awg_codewords",
      "description": "绘制 AWG 码字数据图",
      "description_en": "plot AWG codeword data"
    },
    {
      "action_name": "auto-plot_dio_snapshot",
      "description": "绘制 DIO 快照位图",
      "description_en": "plot a DIO snapshot bit map"
    },
    {
      "action_name": "auto-poll",
      "description": "轮询已订阅数据",
      "description_en": "poll subscribed data"
    },
    {
      "action_name": "auto-reset_waveforms_zeros",
      "description": "将所有波形重置为零值波形",
      "description_en": "reset all waveforms to zero-valued waveforms"
    },
    {
      "action_name": "auto-setc",
      "description": "写入复数节点值",
      "description_en": "write a complex node value"
    },
    {
      "action_name": "auto-setd",
      "description": "写入双精度节点值",
      "description_en": "write a double-precision node value"
    },
    {
      "action_name": "auto-seti",
      "description": "写入整数节点值",
      "description_en": "write an integer node value"
    },
    {
      "action_name": "auto-sets",
      "description": "写入字符串节点值",
      "description_en": "write a string node value"
    },
    {
      "action_name": "auto-setv",
      "description": "写入向量节点值",
      "description_en": "write a vector node value"
    },
    {
      "action_name": "auto-start",
      "description": "按需重新配置 AWG、更新波形并启动所有 AWG",
      "description_en": "reconfigure AWGs as needed, update waveforms, and start all AWGs"
    },
    {
      "action_name": "auto-stop",
      "description": "停止所有 AWG",
      "description_en": "stop all AWGs"
    },
    {
      "action_name": "auto-subs",
      "description": "订阅节点路径更新",
      "description_en": "subscribe to updates for a node path"
    },
    {
      "action_name": "auto-sync",
      "description": "同步设备与服务器状态",
      "description_en": "synchronize device and server state"
    },
    {
      "action_name": "auto-unsubs",
      "description": "取消订阅节点路径更新",
      "description_en": "unsubscribe from updates for a node path"
    },
    {
      "action_name": "auto-awgModule",
      "description": "创建或访问 AWG 编译上传模块",
      "description_en": "create or access the AWG compile/upload module"
    },
    {
      "action_name": "auto-setDebugLevel",
      "description": "设置调试日志级别",
      "description_en": "set the debug logging level"
    },
    {
      "action_name": "auto-connectDevice",
      "description": "连接指定的苏黎世仪器设备",
      "description_en": "connect to a specified Zurich Instruments device"
    },
    {
      "action_name": "auto-listNodesJSON",
      "description": "以 JSON 形式列出可用节点",
      "description_en": "list available nodes in JSON format"
    },
    {
      "action_name": "auto-getString",
      "description": "读取字符串节点值",
      "description_en": "read a string node value"
    },
    {
      "action_name": "auto-getInt",
      "description": "读取整数节点值",
      "description_en": "read an integer node value"
    },
    {
      "action_name": "auto-getDouble",
      "description": "读取双精度节点值",
      "description_en": "read a double-precision node value"
    },
    {
      "action_name": "auto-setInt",
      "description": "写入整数节点值",
      "description_en": "write an integer node value"
    },
    {
      "action_name": "auto-setDouble",
      "description": "写入双精度节点值",
      "description_en": "write a double-precision node value"
    },
    {
      "action_name": "auto-setVector",
      "description": "写入向量节点值",
      "description_en": "write a vector node value"
    },
    {
      "action_name": "auto-setComplex",
      "description": "写入复数节点值",
      "description_en": "write a complex node value"
    },
    {
      "action_name": "auto-getComplex",
      "description": "读取复数节点值",
      "description_en": "read a complex node value"
    },
    {
      "action_name": "auto-get",
      "description": "读取节点值",
      "description_en": "read a node value"
    },
    {
      "action_name": "auto-getAsEvent",
      "description": "以事件形式读取节点值",
      "description_en": "read a node value as an event"
    },
    {
      "action_name": "auto-subscribe",
      "description": "订阅节点更新",
      "description_en": "subscribe to node updates"
    },
    {
      "action_name": "auto-unsubscribe",
      "description": "取消订阅节点更新",
      "description_en": "unsubscribe from node updates"
    },
    {
      "action_name": "auto-get_compilation_count",
      "description": "获取 AWG 程序编译计数",
      "description_en": "get the AWG program compilation count"
    },
    {
      "action_name": "auto-set",
      "description": "写入节点值",
      "description_en": "write a node value"
    },
    {
      "action_name": "auto-execute",
      "description": "执行模块操作",
      "description_en": "execute the module operation"
    },
    {
      "action_name": "auto-get_idn",
      "description": "获取设备识别信息",
      "description_en": "get device identification information"
    }
  ]
}

